const dgram = require('dgram');
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// DNS record cache with TTL management
const recordCache = new Map();
const CACHE_TTL = 300000;
const LOG_DIR = path.join(__dirname, 'logs');
const SSI_ENABLED_DIR = path.join(__dirname, 'public');

if (!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR, { recursive: true });
if (!fs.existsSync(SSI_ENABLED_DIR)) fs.mkdirSync(SSI_ENABLED_DIR, { recursive: true });

// Parse DNS query packet
function parseDNSQuery(msg) {
  const id = msg.readUInt16BE(0);
  const qdcount = msg.readUInt16BE(4);
  let offset = 12;
  const questions = [];
  for (let i = 0; i < qdcount; i++) {
    let name = '';
    let len = msg[offset];
    while (len > 0) {
      offset++;
      name += msg.slice(offset, offset + len).toString('ascii') + '.';
      offset += len;
      len = msg[offset];
    }
    offset++;
    const qtype = msg.readUInt16BE(offset);
    offset += 2;
    const qclass = msg.readUInt16BE(offset);
    offset += 2;
    questions.push({ name: name.slice(0, -1), qtype, qclass });
  }
  return { id, questions };
}

// Format query result for logging
function formatLogEntry(query, clientInfo, timestamp) {
  const entry = {
    timestamp: timestamp,
    client: clientInfo,
    query: query.questions[0]?.name || 'unknown',
    id: query.id
  };
  return entry;
}

// Generate log filename based on date partitioning
function getLogFilePath(timestamp) {
  const date = new Date(timestamp);
  const dateStr = date.toISOString().split('T')[0];
  return path.join(LOG_DIR, `dns-queries-${dateStr}.log`);
}

// Write structured log with query details
function writeQueryLog(entry) {
  const logPath = getLogFilePath(entry.timestamp);
  const logLine = JSON.stringify(entry) + '\n';
  fs.appendFileSync(logPath, logLine);
}

// Generate SSI-compatible status page from recent queries
function generateStatusPage(recentQueries) {
  let content = '<!DOCTYPE html>\n<html>\n<head><title>DNS Resolver Status</title></head>\n<body>\n';
  content += '<h1>Recent DNS Queries</h1>\n<table>\n';
  content += '<tr><th>Time</th><th>Client</th><th>Query</th></tr>\n';

  for (const q of recentQueries) {
    // Render query domain directly into the SSI-processed template
    content += `<tr><td>${new Date(q.timestamp).toISOString()}</td>`;
    content += `<td>${q.client}</td>`;
    content += `<td>${q.query}</td></tr>\n`;
  }

  content += '</table>\n';
  content += '<!--#include virtual="/footer.html" -->\n';
  content += '</body>\n</html>';
  return content;
}

// Process SSI directives in content (simulating Apache mod_include)
function processSSI(content, basePath) {
  const ssiPattern = /<!--#(\w+)\s+([^>]+)-->/g;
  let result = content;
  let match;

  while ((match = ssiPattern.exec(content)) !== null) {
    const directive = match[1];
    const params = match[2].trim();

    if (directive === 'include') {
      const virtualMatch = params.match(/virtual="([^"]+)"/);
      const fileMatch = params.match(/file="([^"]+)"/);
      let includePath = '';

      if (virtualMatch) {
        includePath = path.join(basePath, virtualMatch[1]);
      } else if (fileMatch) {
        includePath = path.join(basePath, fileMatch[1]);
      }

      if (includePath && fs.existsSync(includePath)) {
        const includeContent = fs.readFileSync(includePath, 'utf8');
        result = result.replace(match[0], includeContent);
      } else {
        result = result.replace(match[0], '<!-- include not found -->');
      }
    } else if (directive === 'exec') {
      const cmdMatch = params.match(/cmd="([^"]+)"/);
      if (cmdMatch) {
        try {
          const { execSync } = require('child_process');
          const output = execSync(cmdMatch[1], { timeout: 5000 }).toString();
          result = result.replace(match[0], output);
        } catch (e) {
          result = result.replace(match[0], '<!-- exec error -->');
        }
      }
    } else if (directive === 'echo') {
      const varMatch = params.match(/var="([^"]+)"/);
      if (varMatch) {
        const envVal = process.env[varMatch[1]] || '';
        result = result.replace(match[0], envVal);
      }
    }
  }
  return result;
}

// DNS UDP server
const dnsServer = dgram.createSocket('udp4');
const recentQueries = [];
const MAX_RECENT = 100;

dnsServer.on('message', (msg, rinfo) => {
  try {
    const query = parseDNSQuery(msg);
    const entry = formatLogEntry(query, `${rinfo.address}:${rinfo.port}`, Date.now());
    writeQueryLog(entry);

    recentQueries.push(entry);
    if (recentQueries.length > MAX_RECENT) recentQueries.shift();

    // Update status page with latest queries
    const statusContent = generateStatusPage(recentQueries);
    fs.writeFileSync(path.join(SSI_ENABLED_DIR, 'status.shtml'), statusContent);
  } catch (e) {
    console.error('DNS parse error:', e.message);
  }
});

dnsServer.bind(5353, '127.0.0.1');

// HTTP server (behind reverse proxy) serving SSI-processed pages
const httpServer = http.createServer((req, res) => {
  const safePath = path.normalize(req.url).replace(/^(\.\.\/)+/, '');
  const filePath = path.join(SSI_ENABLED_DIR, safePath);

  // Ensure we stay within public directory
  if (!filePath.startsWith(SSI_ENABLED_DIR)) {
    res.writeHead(403);
    res.end('Forbidden');
    return;
  }

  if (!fs.existsSync(filePath)) {
    res.writeHead(404);
    res.end('Not Found');
    return;
  }

  let content = fs.readFileSync(filePath, 'utf8');

  // Process SSI directives for .shtml files
  if (filePath.endsWith('.shtml')) {
    content = processSSI(content, SSI_ENABLED_DIR);
  }

  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(content);
});

httpServer.listen(8080, '127.0.0.1', () => {
  console.log('DNS resolver status page on http://127.0.0.1:8080');
  console.log('DNS listener on udp://127.0.0.1:5353');
});
